WITH base AS (SELECT id, name, email, country, city, segment, signup_date, credit_limit, age, INITCAP(TRIM(name)) AS name_title, ROUND(credit_limit, 1) AS credit_limit_rounded, COALESCE(segment, 'UNKNOWN') AS segment_clean FROM customers WHERE signup_date >= DATE '2023-03-18' AND segment IS NOT NULL) SELECT *, CORR(credit_limit, age) OVER (PARTITION BY DATE_TRUNC('MONTH', signup_date)) AS corr_credit_limit_age, ROW_NUMBER() OVER (PARTITION BY YEAR(signup_date), segment ORDER BY credit_limit_rounded, id) AS row_seq, MAX(credit_limit_rounded) OVER (PARTITION BY YEAR(signup_date), city) AS signup_date_year_max_credit_limit_rounded, LEAD(credit_limit, 2) OVER (ORDER BY credit_limit_rounded, id) AS next_credit_limit, RANK() OVER (ORDER BY credit_limit_rounded DESC NULLS LAST) AS credit_limit_rounded_rank FROM base;
